window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26680315"]={"book":{"id":26680315,"title":"透过结构看世界","author":"李忠秋","translator":"","publisher":"电子工业出版社","pubdate":"2015-10-1","isbn":"9787121273735","tags":["思维","结构化思考","方法论","金字塔原理","思考力","独立思考","逻辑","结构"],"memCount":9},"np":1,"pb":[13],"idx":[{"i":19440,"t":"透过结构看世界","l":"TF2-1","c":"贺俊丽","g":1,"p":1},{"i":11489,"t":"结论先行","l":"TF2-2","c":"杨颖春","g":1,"p":1},{"i":9986,"t":"概括总结做聚合","l":"TF2-1","c":"贺俊丽","g":1,"p":1},{"i":8773,"t":"透过结构看问题—无方案时找到方案说明白","l":"TF3-2","c":"MECE","g":1,"p":1},{"i":7264,"t":"结构表达的技巧","l":"TF2-2","c":"杨颖春","g":1,"p":1},{"i":6871,"t":"\"掌握结构式的沟通技巧 \"","l":"TF2-1","c":"林の雪","g":1,"p":1},{"i":6600,"t":"如何借助总分总结构提升逻辑表达力","l":"TF2-2","c":"杨颖春","g":1,"p":1},{"i":6362,"t":"SCQA法——分析帮助确定问题","l":"TF1-1","c":"骏飞","g":1,"p":1},{"i":5243,"t":"分步催生聚焦问题","l":"TF1-2","c":"无敌","g":1,"p":1},{"i":4287,"t":"SCQA法，分析帮助确定问题","l":"TF1-1","c":"刘雅恕","g":0,"p":1},{"i":1389,"t":"三点帮你养成优化思考结构的习惯。","l":"TF2-3","c":"故……","g":0,"p":1},{"i":925,"t":"结论先行，以上统下","l":"TF2-1","c":"张臻凯","g":1,"p":1},{"i":157,"t":"疑问回答式分解法","l":"TF2-2","c":"不如跳舞","g":0,"p":1}],"ms":[{"id":19440,"topic":"透过结构看世界","learn_goal":"","remark":"作者李忠秋曾任教于国家部委直属本科院校，后进入管理咨询行业成为一名职业讲师。因意识到思考力提升比知识更重要后，开始专注于结构思考力这一领域，是国内在该领域内最有影响力的研究、实践与推广者。","level":"TF2-1","duration":40,"status":30,"type":0,"chaishujia":{"username":"贺俊丽","city":"呼和浩特市"},"club":{"name":"呼和浩特敕勒川分舵","city":"呼和浩特"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>各位小伙伴们大家晚上好，我是贺俊丽。\u003c/strong>\u003cbr>\u003cstrong>我的三个标签：HR培训师/咨询师，葡萄酒品鉴师、在路上的拆书家，终身学习者。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先在开始之前说一下分组的事情，左边的这4位小伙伴们为一组，右边的4位小伙伴们为一组，每组选出一位组长，请同一小组的小伙伴们们围坐到一个大桌前，等一下方便大家进行组内计论和分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在跟随我完成本次RIA现场学习后，学习者能够：在需要对一堆素材或海量信息进行总结提炼时，运用“概括总结做聚合”的方法，理出头绪，以便“提纲挈领”、思考清晰，表达有力。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":23813,"quote":"\u003cp>\u003cstrong>我今天给大家带来的拆页源自《透过结构看世界》p133~134页，\u003c/strong>\u003cbr>\u003cstrong>我分享的主题是《自下而上搭建金字塔结构的方式：概括总结做聚合》。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>图书介绍FAB法\u003c/strong>\u003cbr>\u003cstrong>F特征：《透过结构看世界》作者李忠秋曾任教于国家部委直属本科院校，后进入管理咨询行业成为一名职业讲师。因意识到思考力提升比知识更重要后，开始专注于结构思考力这一领域，是国内在该领域内最有影响力的研究、实践与推广者。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《透过结构看世界》这本书共3个篇章，分别为理念篇、方法篇和应用篇。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>理念篇：重点介绍结构思考力的原理、理论依据与基本模型。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方法篇：基于结构思考力的三层次模型，分别从理解、重构、呈现三个方面对结构思考力具体的方法、工具展开阐述。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应用篇：分别介绍结构思考力在表达、问题解决、会议共识三个方面的实际应用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A优势：《透过结构看世界》这本书最大的优势在于图文并茂的阐述了结构思考力的理念、方法与应用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>与芭芭拉﹒明托的《金字塔原理》相比较，《透过结构看世界》这本书运用更符合中国企业及中国人的特点进行诠释，更易于我们进行阅读和理解，没有那么生涩和艰难。\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>B利益：（书对学习者的价值）结构思考力是这个时代所有人的必备技能。每个人几乎每时每刻都在面临着选择和决策。如果没有结构，我们的思维就很容易从一点漂到另一点，却总也无法得出一个有效结论。通过本书可以带动更多国人开启结构思考力的旅程，运用结构思考力做到思考清晰、表达有力、生活清爽、工作高效，并养成以结构的视角去审视生活与工作的习惯，让生活与工作变得更加高品质、高效率！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（片段的价值）我今天拆的片段叫概括总结做聚合，这个片段来自于《透过结构看世界》p133~134页，这个片段教会我们在面对一堆素材或信息时，需要加以整理、梳理，理出头绪，以便“提纲挈领”的情况下，需要我们采取自下而上搭建金字塔结构的方式。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段主题：自下而上搭建金字塔结构的方式：概括总结做聚合\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段选自：《透过结构看世界》p133~134页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在日常生活工作中，我们经常遇到另外一种情况，就是面对一堆素材或信息，需要加以整理、梳理，理出头绪，以便“提纲挈领”。比如工作总结就是如此。在这样的情况下，就需要我们采取自下而上搭建金字塔结构的方式，叫做概括总结做聚合。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>采取这种方式有三个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（1）收集信息。将能够收集到的信息全部罗列出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（2）信息分类。按照归类分组的原则，确保同一组的信息属于同一个范畴。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（3）概括总结。将每个分类概括出一个结论。寻找每组信息资料的共性，将共性概括为结论，然后继续往上概括，直到金字塔的塔顶得出最终的结论为止。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们现在以生活中介绍异性朋友为例，说明此方式的运用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>假如有人向你单位的一位女同事介绍男朋友，你问他那个小伙子怎样呀？他说，那个小伙子真不错，个头高，大学毕业，长相好，待人和气，潇洒活泼，逻辑思维能力强，富有同情心，在大型企业从事设计工作，工资高……\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你听完这样的介绍，感觉信息不少，但有些乱。所以你需要将这些信息梳理一下，分成三类，每类给出一个结论，最后概括出一个结论，再向你的女同事介绍，就会很精彩。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>看到大家已经基本读完了，我用自己的语言和经历和大家分享下这个片段。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>概括总结做聚合：是一种方式方法，此法可以帮助人们在工作或生活中场景中，分析杂乱无章的事情时很难马上找到主题的情况下，通过自下而上的思考方式，用于帮助人们梳理信息，逐渐找到重点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Where】（也可以归结在WHAT中）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用场景：需要将散乱的、关键词式的海量信息进行提炼总结归纳并清晰传递出来的工作或者生活场景中。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界：亲友及家人间度假闲聊场景则不需要。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人们在工作或生活中场景中，往往会遇到散乱的、关键词式的海量信息，这时就需要用概括总结做聚合的方法清晰简介的提炼出来并清晰表达。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不运用“概括总结做聚合”的话，别人听我们说话，往往会让人觉得词不达意、不知所云、杂乱无章、缺乏逻辑、没有结构，达不到有效沟通的目的！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>收集自己所能接触到的所有的信息，可以通过网络查找、书籍阅读、咨询他人、自己观察等方法，这一步尽量做到“全”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是重点和难点，此时需要锻炼自己概括总结的能力：判断这个信息的深一层次或者它的本质讲的是哪一个方面，尽量把相同范畴的信息归类到一起。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：简要概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这一步要求为上一步归好的一类信息找到一个恰当的修饰性词语或短语，形成结论性的陈述句。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【举个反面的例子：描述自己的相关经验】【复工后疫情期间培训工作汇报】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3月份的一天，领导组织召开一次线上会议，要求各个板块的负责人汇报下这段时间的工作内容，我作为培训部负责人，说了如下片段式关键词：线下转线上，微信群+钉钉群+钉钉圈子、朋友圈推广、学习业内大咖的经验、开了6次线上课程、累计听课人次，培训内容......，领导的注意力没有集中，我的汇报就随便过去了，会议进入下一个工作议题了（自我感觉就像自己消极怠工没有好好工作一样，我很忐忑和不甘心，这就是不按照“概括总结做聚合”这个行动建议去做的坏处吧）。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【反思】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自下而上搭建金字塔结构的方式：概括总结做聚合方式进行汇报\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>线下转线上，微信群+钉钉群+钉钉圈子、朋友圈推广、开了6次线上课程、累计听课人次，培训内容......，领导的注意力没有集中，我的汇报就随便过去了，进入下一个工作议题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>把相同范畴的信息放到一起\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第1类信息：当下培训大环境及同行的做法：学习业内大咖的经验及案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第2类信息：我部门的做法：微信群+钉钉群+钉钉圈子、朋友圈授课、累计听课人次，培训内容、培训效果等......\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第3类信息：推广课程的方式：线上推广\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：简要概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>找到修饰词形成结论性陈述句：比如：受大环境影响，虽然不能按计划线下开课，但是通过线上的方式，增加了客户的粘性，并且更加认同公司品牌。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家设计提问（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请各位小伙伴们回忆下：近期你有没有在某个工作场景下，需要对一堆素材或海量信息进行总结提炼时，词不达意，缺乏逻辑、没有结构，最终汇报或沟通的效果不佳的案例呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子（当然这是个虚拟的例子），近期你有没有在会议室参会，讨论一个项目的时候，突然被你的上级或者老板抓起来，要求你进行项目的总结或者汇报，你该如何梳理总结呢，可以和大家分享下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>逸群同学的分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>上个月在电检资质年检的项目协调会上，本来是技术人员汇报项目，当时我有一些走神，在想其他的事情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果老板突然问我：兰经理，你来汇报下，你们部门在证书、证照管理这一块有什么见解，是怎么做的？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我当时因为走神，也是新来的，突然被提问，起来巴拉巴拉说了一堆，无关紧要的，有的没的都说了，然而自己觉得很乱，我一头雾水，老板也是一头雾水，汇报效果不好，如果可以提前对这个事情进行分类总结，利用贺老师教的方法，效果会非常好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家设计提问（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>刚才我们回顾了一个失败的经历，如果时光倒流回到当初，按照今天所学的拆页中“概括总结做聚合”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（用【（1）收集信息（2）信息分类（3）概括总结】这三步来积极应对这个事情），您可以怎么做，才能更好的解决这个问题呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请组长组织本组内成员，大家每个人都尽量表达一下，咱们用1-2分钟时间来沟通下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>依然是来自于逸群同学的分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>继续就刚才的案例进行分享如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果当时我学习了这个方法的话\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我部门管理的证照，比如：营业执照、消防员证件、电检资质证书等，按照类别先报数；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>相同范畴的信息呢，我把他们归类到一起：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>营业执照是怎么管理的、消防员证件有几个人分别是怎么管理的、电检资质证是否年检以及怎么管理的，这个还是能说清楚的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：检验概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结一句话，公司证照在有序管理中，需要工程部、设计部、财务部配合。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家把这个事情说的更明确一些，会呈现出不同的效果，这个方法今天学习后感觉非常受用，谢谢大家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我今天的拆书分享完毕，感谢大家的参与和学习，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1763532790000,"updated_at":1763553682000,"ria":true},{"id":11489,"topic":"结论先行","learn_goal":"","remark":"杨颖春TF2-2定级","level":"TF2-2","duration":20,"status":19,"type":0,"chaishujia":{"username":"杨颖春","city":"厦门"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>我叫杨颖春，我的3个标签是公司职员、生命舞者、一级拆书家，今天定级TF2-2，我们先分下组，左边一组右边一组，希望通过本次学习，学习者能够运用本拆知识能够表达清晰一件事，达到接受者能清晰知道我们的结论是什么。\u003c/p>\u003cp>今天我要给大家分享的内容来自李忠秋老师写的《透过结构看世界》。\u003c/p>\u003cp>【F部分：特征，核心“书”】\u003c/p>\u003cp>这本《透过结构看世界》的作者李忠秋老师本身就是一个运用结构化思考的成熟佳品，其所著这本书，通过对结构思考力的剖析和讲解，使你觉察并改善自身的思考结构，养成科学思维的习惯，成为善思、善讲、善写的人才，从而帮助你从思、言、行这三个层次提升个人的实战力。\u003c/p>\u003cp>【A部分：优势，重点是“比较”】\u003c/p>\u003cp>这本书是理论、方法、应用相结合，本书观点鲜明，结构清晰，通俗易懂，给人印象深刻，是实用性非常强的一本书，彩色手绘图示，精美展现，是该书的一大亮点；李忠秋老师围绕着透过结构看世界，层层分解，向我们传达了洞悉本质的思考艺术，为读者树立了运用结构思考力的最佳典范。\u003c/p>\u003cp>【B利益：学习者获得收获】\u003c/p>\u003cp>你在汇报工作时是否有被领导训斥你说了这么多到底在说什么，或与同事沟通项目进展时，同事问你找我到底要我做什么，我现在没空听你长篇大论，等你想清楚了在找我等等，那么这本书可以告诉你怎样花最少的时间将汇报工作，与同事沟通达到预期甚至意想不到的效果。\u003c/p>","ratings_count":1,"texts":[{"id":15408,"quote":"\u003cp>【R 阅读原文】拆页来自李忠秋《透过结构看世界》之结论先行P74-75节选\u003c/p>\u003cp> “以名举实，以辞抒意，以说出故”，《墨子.小取篇》作为墨家名辩之学的精华所在，对基于清晰思考的表达做了明确的论述，各种事物称为“实”，“实”的称谓便是“名”，比如这是一匹马，“这”就是实，“一匹马”就是名，名与实一起成为“辞”，有了辞才能达意，才叫结论。 如图5-7所示。\u003c/p>\u003cp>想要表达清晰，就必须有结论。无论传达什么信息，都是为了让对方知道结论是什么。如前面提到的机毁人亡的事故，假如你是机场负责人，当你向上级领导汇报时，你首先说结论：“今天发生了一起一等事故。”上级领导一听就明白了事故的严重性。然后，他需要听你讲述发生事故的原因，下一步需要做的工作，准备采取的措施等。若下级行讲发生事故的现象、处理情况等，上级领导会不耐烦甚至勃然大怒。\u003c/p>\u003cp>结论先行不仅仅是先说结论这么简单，重点是要有结论。有一次一家企业的培训负责人很晚打电话给我，希望我帮她修改明天上午的述职报告，第二述职结束后打电话给我反馈了结果。说改之前的报告有同事看过，改完以后的述职报告会那同事也在场。改之前她同事的评价是，看完这个报告能感觉出来她是一个踏踏实实完成工作任务的职业经理人，面改完后的报告体现出，他就是一个有思想的高级职业经理人。到底什么样的变化会有这样的评价呢？其实很简单，就是两个结论的提出。改之前报告分为两部分2014培训工作总结和2015培训工作规划。两个都不是结论，改完之后的是2014年打造具有生命力的培训项目，2015年打造为业务提供支持的培训体系。述职完后，人们可以很容易地记住她的两个观点，而且每个部分下面都有相应的结论作为支撑。这就是有结论和没结论的差别。\u003c/p>","explains":"\u003cp>好，大家都阅读完了本片段，\u003c/p>\u003cp>What：这本书告诉我们，要想表达清晰，就必须有结论无论传达什么信息，都是为了让对方知道结论是什么，先表明观点，然后再依次对观点进行说明。\u003c/p>\u003cp>Why：为什么要结论先行呢，书的例子告诉我们领导关注的或同事所关注的是结果，过程只是对结果进行的论证\u003c/p>\u003cp>How：拆页里已经详细给出了步骤\u003c/p>\u003cp>1、论，结论先行，首先表明总结观点\u003c/p>\u003cp>2、依次阐明要点，对观点进行说明\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>在现实中，很多人会说，我们中国人并不习惯这么讲，就像人与人之间在沟通中牵扯到情感时，先抛出一个结论可能会给人感觉目的性特别强，人的理性上接受不了；可以在工作场合中，特别是主题会议，需要结论先行，因大家的事务都非常多，谁也没而心去听你讲，只有先知道我们要的结论是什么，进行有针对性的讨论，才能提高效率，达到会议的目的。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong> \u003c/p>\u003cp>1、 生活中不一定要用结论先行，特别是在于情感方面不适用。\u003c/p>\u003cp>2、 对于工作中复杂问题，也不适用，复杂的问题需要经过缜密的思才，形成一定的结论，而不是根据经验很轻易的给出一个结论，就像我们所知道的刻舟求剑，纸上谈兵，就是类似这样的。\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>由于公司的产品有颗料停产了，需要对替代的物料进行验证是否可达到相同的功效，这是一个公司的主打产品不能停产，公司上层最终想知道的结果是这颗物料是否能替代原有的物料，所产生的影响，功能性要求是否符合产品本身的种需求，质检组长将测试报告拿给我，十几页的报告全是测试过程，结果只有一句话，未说明可以替代的理由，要知道理由还需要看报告的人自己去梳理，因此被我退件了，报告是给决策者看的，他关心的结论是什么而不过是过程，因此报告先说结果是否可替代，接着说可以替代的理由，最终再整理理由形成的原因在哪，这样可以节省看报告人的时间。\u003c/p>\u003cp>\u003cstrong>这样做的好处就是：\u003c/strong>处理一些简单的工作、工作汇报、早会等使用结论先行可以节省大家的时间，大家的关注点可以跟宣讲者或组织者有统一的思想，形成共识，在行动上有一致的行动，而不是你说你的，我说我的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2催化学习者应用】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化1，激活场景，\u003c/strong>\u003c/p>\u003cp>请小伙伴想下在今后，会将本片段运用到哪个场景，比如像课程设计、老板汇报工作、团队建设计划、跨部门协调等，大家思考想出具体场景，然后运用本片段知识加工一个例子，说明你在此场景下可以运用本片段知识，我们花3分钟时间组内讨论下，稍后请小伙伴给我们分享下他的场景。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>在过2周要做线上拆书，在准备线上课程设计时会运用今天所学片段。\u003c/p>\u003cp>\u003cstrong>分步催化2，催化应用（规划行动步骤）\u003c/strong>\u003c/p>\u003cp>请大家想一下，今天片段中学到的步骤，你会怎样运用到你的场景中？稍后请一位小伙伴分享下“你会怎么做？”\u003c/p>\u003cp>大家讨论的非常激烈，现在我们请这位小伙伴分享下他会怎么做。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>我在准备拆研班线上一小时的预备表内容，学了本片段的知识，我可以将本片段的知识应用在预备表整个环节的设计当中，在自我介绍和图书介绍完之后，我会增加一个学习地图，学习地图呈现三个片段讲了什么内容，同时在每个片段要做哪些事项，比如说片段一关联自己过往经验，片段三应用此片段到未来的运用，学习地图包含了三个片段的知识点，还有学习者在学习过程当中预期的心理状态把他融到学习地图里；接下来讲三个片段具体讲解的呈现；三个片段讲解完后，再来一个总的归纳总结，对三个片段进行一个概括；这样的话，学习者对于片段的知识有一个很清晰的脉络。\u003c/p>\u003cp>\u003cstrong>结束语，\u003c/strong>\u003c/p>\u003cp>谢谢这位小伙伴的分享，他向我们很好的呈现了今天所学习的步骤，论，结论先行，先表明观点，然后再依次对观点进行说明，用总的一个方式，里面有一个学习地图，接着对这么内容进行一些分解，到了最后又给我们把今天所学的东西做了一个总的概括，是非常好的一个案例，今天学习的目标，汇报工作也好，分享美好的事物也好，以他们舒服的方式表达自己的观点，再对观点进行解说，无意间就会产生共鸣，达到我们共同的目标，今天我的分享结论先行，希望能给大家带来收获，今天的拆书到些结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1620253648000,"updated_at":1620569887000,"ria":true},{"id":9986,"topic":"概括总结做聚合","learn_goal":"","remark":"F特征：《透过结构看世界》作者李忠秋曾任教于国家部委直属本科院校，后进入管理咨询行业成为一名职业讲师。因意识到思考力提升比知识更重要后，开始专注于结构思考力这一领域，是国内在该领域内最有影响力的研究、实践与推广者。\nA优势：《结构思考力》、《透过结构看世界》的核心理念源自芭芭拉﹒明托的《金字塔原理》，运用更符合中国企业及中国人的特点进行诠释。\nB利益：结构思考力是这个时代所有人的必备技能。每个人几乎每时每刻都在面临着选择和决策。如果没有结构，我们的思维就很容易从一点漂到另一点，却总也无法得出一个有效结论。通过本书可以带动更多国人开启结构思考力的旅程，运用结构思考力做到思考清晰、表达有力、生活清爽、工作高效，并养成以结构的视角去审视生活与工作的习惯，让生活与工作变得更加高品质、高效率！","level":"TF2-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"贺俊丽","city":"呼和浩特市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先在开始之前说一下分组的事情，左边的这4位小伙伴们为一组，右边的4位小伙伴们为一组，每组选出一位组长，请同一小组的小伙伴们们围坐到一个大桌前，等一下方便大家进行组内计论和分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>各位小伙伴们大家晚上好，我是贺俊丽。\u003c/strong>\u003cbr>\u003cstrong>我的三个标签：HR培训师/咨询师（14年的HR从业经验），葡萄酒品鉴师（WSET认证的，2年澳洲红酒运营经验）、在路上的拆书家，终身学习者。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在跟随我完成本次RIA现场学习后，学习者能够：在需要对一堆素材或海量信息进行总结提炼时，运用“概括总结做聚合”的方法，理出头绪，以便“提纲挈领”、思考清晰，表达有力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我今天给大家带来的拆页源自《透过结构看世界》p133~134页，\u003c/strong>\u003cbr>\u003cstrong>我分享的主题是《自下而上搭建金字塔结构的方式：概括总结做聚合》。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>图书介绍FAB法\u003c/strong>\u003cbr>\u003cstrong>F特征：《透过结构看世界》作者李忠秋曾任教于国家部委直属本科院校，后进入管理咨询行业成为一名职业讲师。因意识到思考力提升比知识更重要后，开始专注于结构思考力这一领域，是国内在该领域内最有影响力的研究、实践与推广者。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《透过结构看世界》这本书共3个篇章，分别为理念篇、方法篇和应用篇。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>理念篇：重点介绍结构思考力的原理、理论依据与基本模型。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方法篇：基于结构思考力的三层次模型，分别从理解、重构、呈现三个方面对结构思考力具体的方法、工具展开阐述。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应用篇：分别介绍结构思考力在表达、问题解决、会议共识三个方面的实际应用。\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>A优势：《透过结构看世界》这本书最大的优势在于图文并茂的阐述了结构思考力的理念、方法与应用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>与芭芭拉﹒明托的《金字塔原理》相比较，《透过结构看世界》这本书运用更符合中国企业及中国人的特点进行诠释，更易于我们进行阅读和理解，没有那么生涩和艰难。\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>B利益：（书对学习者的价值）结构思考力是这个时代所有人的必备技能。每个人几乎每时每刻都在面临着选择和决策。如果没有结构，我们的思维就很容易从一点漂到另一点，却总也无法得出一个有效结论。通过本书可以带动更多国人开启结构思考力的旅程，运用结构思考力做到思考清晰、表达有力、生活清爽、工作高效，并养成以结构的视角去审视生活与工作的习惯，让生活与工作变得更加高品质、高效率！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（片段的价值）我今天拆的片段叫概括总结做聚合，这个片段来自于《透过结构看世界》p133~134页，这个片段教会我们在面对一堆素材或信息时，需要加以整理、梳理，理出头绪，以便“提纲挈领”的情况下，需要我们采取自下而上搭建金字塔结构的方式，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请大家用1分钟左右时间阅读拆页片段，读完后抬头示意。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":13817,"quote":"\u003cp>\u003cstrong>片段主题：自下而上搭建金字塔结构的方式：概括总结做聚合\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段选自：《透过结构看世界》p133~134页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在日常生活工作中，我们经常遇到另外一种情况，就是面对一堆素材或信息，需要加以整理、梳理，理出头绪，以便“提纲挈领”。比如工作总结就是如此。在这样的情况下，就需要我们采取自下而上搭建金字塔结构的方式，叫做概括总结做聚合。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>采取这种方式有三个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（1）收集信息。将能够收集到的信息全部罗列出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（2）信息分类。按照归类分组的原则，确保同一组的信息属于同一个范畴。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（3）概括总结。将每个分类概括出一个结论。寻找每组信息资料的共性，将共性概括为结论，然后继续往上概括，直到金字塔的塔顶得出最终的结论为止。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们现在以生活中介绍异性朋友为例，说明此方式的运用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>假如有人向你单位的一位女同事介绍男朋友，你问他那个小伙子怎样呀？他说，那个小伙子真不错，个头高，大学毕业，长相好，待人和气，潇洒活泼，逻辑思维能力强，富有同情心，在大型企业从事设计工作，工资高……\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你听完这样的介绍，感觉信息不少，但有些乱。所以你需要将这些信息梳理一下，分成三类，每类给出一个结论，最后概括出一个结论，再向你的女同事介绍，就会很精彩。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>看到大家已经基本读完了，我用自己的语言和经历和大家分享下这个片段。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>概括总结做聚合：是一种方式方法，此法可以帮助人们在工作或生活中场景中，分析杂乱无章的事情时很难马上找到主题的情况下，通过自下而上的思考方式，用于帮助人们梳理信息，逐渐找到重点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Where】（也可以归结在WHAT中）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用场景：需要将散乱的、关键词式的海量信息进行提炼总结归纳并清晰传递出来的工作或者生活场景中。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界：亲友及家人间度假闲聊场景则不需要。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人们在工作或生活中场景中，往往会遇到散乱的、关键词式的海量信息，这时就需要用概括总结做聚合的方法清晰简介的提炼出来并清晰表达。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不运用“概括总结做聚合”的话，别人听我们说话，往往会让人觉得词不达意、不知所云、杂乱无章、缺乏逻辑、没有结构，达不到有效沟通的目的！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>收集自己所能接触到的所有的信息，可以通过网络查找、书籍阅读、咨询他人、自己观察等方法，这一步尽量做到“全”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是重点和难点，此时需要锻炼自己概括总结的能力：判断这个信息的深一层次或者它的本质讲的是哪一个方面，尽量把相同范畴的信息归类到一起。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：简要概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这一步要求为上一步归好的一类信息找到一个恰当的修饰性词语或短语，形成结论性的陈述句。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【举个反面的例子：描述自己的相关经验】【复工后疫情期间培训工作汇报】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3月份开始复工后的第一天，领导组织召开一次复工会议，要求各个板块的负责人汇报下疫情期间的工作内容，我作为培训部负责人，说了如下片段式关键词：线下转线上，微信群+钉钉群+钉钉圈子、朋友圈推广、学习业内大咖的经验、开了6次线上课程、累计听课人次，培训内容......，领导的注意力没有集中，我的汇报就随便过去了，会议进入下一个工作议题了（自我感觉就像在疫情在家办公这个期间消极怠工没有好好工作一样，我很忐忑和不甘心，这就是不按照“概括总结做聚合\u003c/strong>\u003c/p>\u003cp>\u003cstrong>”这个行动建议去做的坏处吧）。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【反思】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自下而上搭建金字塔结构的方式：概括总结做聚合方式进行汇报\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>线下转线上，微信群+钉钉群+钉钉圈子、朋友圈推广、开了6次线上课程、累计听课人次，培训内容......，领导的注意力没有集中，我的汇报就随便过去了，进入下一个工作议题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>把相同范畴的信息放到一起\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第1类信息：疫情下培训大环境及同行的做法：学习业内大咖的经验及案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第2类信息：我部门的做法：微信群+钉钉群+钉钉圈子、朋友圈授课、累计听课人次，培训内容、培训效果等......\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第3类信息：推广课程的方式：线上推广\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：简要概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>找到修饰词形成结论性陈述句：比如：受疫情影响，虽然不能按计划线下开课，但是通过线上的方式，增加了客户的粘性，并且更加认同卓悦品牌。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家设计提问（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请各位小伙伴们回忆下：近期你有没有在某个工作场景下，需要对一堆素材或海量信息进行总结提炼时，词不达意，缺乏逻辑、没有结构，最终汇报或沟通的效果不佳的案例呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子（当然这是个虚拟的例子），近期你有没有在会议室参会，讨论一个项目的时候，突然被你的上级或者老板抓起来，要求你进行项目的总结或者汇报，你该如何梳理总结呢，可以和大家分享下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>逸群同学的分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>上个月在电检资质年检的项目协调会上，本来是技术人员汇报项目，当时我有一些走神，在想其他的事情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果老板突然问我：兰经理，你来汇报下，你们部门在证书、证照管理这一块有什么见解，是怎么做的？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我当时因为走神，也是新来的，突然被提问，起来巴拉巴拉说了一堆，无关紧要的，有的没的都说了，然而自己觉得很乱，我一头雾水，老板也是一头雾水，汇报效果不好，如果可以提前对这个事情进行分类总结，利用贺老师教的方法，效果会非常好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家设计提问（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>刚才我们回顾了一个失败的经历，如果时光倒流回到当初，按照今天所学的拆页中“概括总结做聚合”（用【（1）收集信息（2）信息分类（3）概括总结】这三步来积极应对这个事情），您可以怎么做，才能更好的解决这个问题呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请组长组织本组内成员，大家每个人都尽量表达一下，咱们用1-2分钟时间来沟通下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>依然是来自于逸群同学的分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>继续就刚才的案例进行分享如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果当时我学习了这个方法的话\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：全面收集信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我部门管理的证照，比如：营业执照、消防员证件、电检资质证书等，按照类别先报数；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：清晰结构提炼：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>相同范畴的信息呢，我把他们归类到一起：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>营业执照是怎么管理的、消防员证件有几个人分别是怎么管理的、电检资质证是否年检以及怎么管理的，这个还是能说清楚的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：检验概括总结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结一句话，公司证照在有序管理中，需要工程部、设计部、财务部配合。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家把这个事情说的更明确一些，会呈现出不同的效果，这个方法今天学习后感觉非常受用，谢谢大家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我今天的拆书分享完毕，感谢大家的参与和学习，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1592665040000,"updated_at":1593329723000,"ria":true},{"id":8773,"topic":"透过结构看问题—无方案时找到方案说明白","learn_goal":"学习者在遇到问题没有方案时，能够通过结构化分析，寻找解决方案","remark":"事件场景：生活、工作中我们总会遇到这样的情况，面对问题，我们想到的都是各种困难的坏的结果，找寻解决方案，也总是随机出现的灵感，并无章法。很多方案也是针对表面问题的方案，不解决根本问题。\r\n提问：遇到这类遇事干着急，没办法，你之前是如何处理的呢？单纯发泄情绪，还是做点尝试，然后祈祷上天给个好结果？还可以怎样做？\r\n影响：不能分析问题找到解决方案，会给我们带来极大的影响。生活中的问题不能解决，我们就要承担问题带来的不利后果，也许伴随终生；工作上的问题不能解决，那就是没有价值，不仅不会有晋升发展，更甚至可能末位淘汰丢了工作。\r\n透过结构，来分析问题、挖掘原因，假设、验证，一步步的找寻到解决方案，并科学呈现","level":"TF3-2","duration":90,"status":29,"type":0,"chaishujia":{"username":"MECE","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是张鹏，很高兴和大家一起拆书学习。\r\n今天分享的主题是 透过结构看问题—无方案时找到方案说明白\r\n为了保证我们今天的学习效果，我们先来分一下组。书桌左手边为一组，右手边为二组。\r\n今天的学习目标是：学习后，学习者在遇到问题没有方案时（where），能够利用结构化分析，寻找（行为）解决方案（界定）。\r\n事件场景：您是否遇到这样的情况，产品销量不好，老板一句话就要提升30%销量。经济形势不好，顾客不愿意买，我能怎么办？面对问题，我们想到的都是各种困难的坏的结果，找寻解决方案，也总是随机出现的灵感，并无章法。很多方案也是针对表面问题的方案，不解决根本问题。\r\n提问：遇到这类遇事干着急，没办法的情况，你之前是如何处理的呢？单纯发泄情绪，或者随便做点尝试，然后祈祷上天给个好结果吗？还可以怎样做？\r\n影响：不能分析问题找到解决方案，会给我们带来极大的影响。生活中的问题不能解决，我们就要承担问题带来的不利后果，也许伴随终生；工作上的问题不能解决，那就是没有价值，不仅不会有晋升发展，更甚至可能末位淘汰丢了工作。\r\n解决：《透过结构看世界》这本书教给我们结构的思考。\r\n学习今天的片段，我们可以利用模型透过结构，来分析问题、挖掘原因，大胆假设、小心求证，一步步的找寻到解决方案，并做科学的呈现。\r\n &nbsp;&nbsp;\u003c/p>\u003cp>下面，我给大家发张测试题，看看自己面对问题找方案的能力怎么样，1代表最不符合，6代表最符合，请仔细阅读每一句话，根据自己的实际情况进行打分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1我看到的问题都是最表面的现象\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2我看到了问题，也很难挖掘出根本原因\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3我不能找到适当的问题切入点建立假设\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4我从不通过数据收集等方式验证假设\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5我不满意自己对问题结果的输出方式\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>技能点：激活学习者经验把知识改编成量表自测题\u003c/p>\u003cp>大家的打分怎么样呢？我们来看一下，看看是不是大多数人遇到的情况一样。\u003c/p>\u003cp>如果您在25分及以上。\u003c/p>\u003cp>您面对问题找方案的能力为1颗星，您面对问题时，看到的是问题的表象，未能有效分析其本质及根本原因，欠缺设立假设、数据验证等方法，在得到解决方案后也无法科学表达。建议，认真学习接下来要讲的透过结构看问题技巧，并做结合自身情况做深入分析、对方法多加练习。\u003c/p>\u003cp>如果您在15-24分之间。\u003c/p>\u003cp>您面对问题找方案的能力为3颗星，您在分析问题探索方案方面，有一定的心得和实践，但在挖掘核心问题、找寻根本原因、理解问题、重构问题、呈现结果等一个或几个方面仍存在短板。建议在学习今天的方法后，有针对性加强。\u003c/p>\u003cp>如果您在15分以下。\u003c/p>\u003cp>说明您面对问题找方案的能力为5颗星，您有深厚的功力去分析问题并找到解决方案。建议，您可以充分发挥自身结构化思考能力，将其跨界联合其他技能在更多领域应用，创造更大价值。另外，可将心得经验传授给更多朋友，让更多人受益。\u003c/p>\u003cp>让大家做这个测试题，是希望能让我们更清晰地理解今天拆解的主题——透过结构看问题—无方案时找到方案说明白。这几个问题，是在遇到问题，找寻方法时可能会遇到的情况。 无论在生活还是工作中，我们都必将遇到问题，那如何能看透问题找到解决方案呢?接下来，请大家阅读我发给大家的拆页。\u003c/p>","ratings_count":1,"texts":[{"id":12477,"quote":"\u003cp>透过结构看问题一一无方案时，找到方案说明白\u003c/p>\u003cp>结构思考的方式不只适用于工作状态，在生活中合理地运用，可以摆脱琐事纠缠，让生活清爽，事半功倍。如果认识到这一点，就要在日常生活中有意识地培养结构思考力，不放过每一次处理事件的机会。日积月累，终能达到洞悉问题本质的目的。所谓洞悉本质:就是在诸多现象中找到核心点，看清楚问题真正的原因，并导出正确的解决方法。\u003c/p>\u003cp>解决问题既是一门科学，又是一种艺术。说其是科学，就意味着解决问题有经过验证的科学步骤和方法。说其是艺术，证明每个问题都有其独特性，只照搬固定的模式和工具是不够的，要根据问题的特点，灵活选择方法并加以组合。因此改变固有的思维模式，客观、系统、结构地思考才是解决问题的必杀技。在此之前，须反复强调“按流程解决问题＂。只要抓住流程，作为问题解決者就已踏上了解决问题的正确道路。\u003c/p>","explains":"\u003cp>好，我发现大家已经读完了，那么，问个问题，书中说有意识地培养结构思考力，最终能达到什么样的目的?\u003c/p>\u003cp>洞悉问题本质\u003c/p>\u003cp>那么洞悉问题本质的定义是什么?\u003c/p>\u003cp>是在诸多现象中找到核心点，看清楚问题真正的原因，并导出正确的解决方法。\u003c/p>\u003cp>技能点：拆书家讲解引导和学习者简短互动\u003c/p>\u003cp>what\u003c/p>\u003cp>是的，这个片段告诉我们有意识地培养结构思考力，最终能达到洞悉问题本质的目的，。洞悉问题本质是在诸多现象中找到核心点，看清楚问题真正的原因，并导出正确的解决方法。\u003c/p>\u003cp>看过洞悉本质的定义，我们来看这样一个案例。小明生病了去看医生，说:”医生，我很难过，我头疼的厉害”。医生说头疼啊，那我给你开点止疼的药。你说这个算不算洞悉本质找到解决方法?\u003c/p>\u003cp>不算\u003c/p>\u003cp>对，因为他没有找到头疼这个表面问题下，更核心的问题及根本原因。\u003c/p>\u003cp>那同样这个案例，小明说我头疼。医生不问情况、不做检查，就说那应该是感冒了，给你开感冒药。你说这个算不算洞悉本质找到解决方法？\u003c/p>\u003cp>不算\u003c/p>\u003cp>对，因为医生虽然拨开了问题表象，找到了假设一个根本问题。但他没有去通过各种检查来验证他的假设，假设还很可能是错误的呢，给出的解决方案将更加不靠谱。所以，也不能算是洞悉问题本质。\u003c/p>\u003cp>那么合乎洞悉本质的过程应该是。\u003c/p>\u003cp>医生发现头疼的表面问题，找到更深层次的问题，身体生病了。\u003c/p>\u003cp>通过小明对近几天生活状态的描述，判断引发生病的根本原因，判断身体最可能生什么病。\u003c/p>\u003cp>结合初步的判断，针对性使用化验、透视等方法验证判断。\u003c/p>\u003cp>确定病情后，给予针对性治疗方案。同时，为了达成结构化思考的要求，还要用言简意赅的呈现表达出来。\u003c/p>\u003cp>why\u003c/p>\u003cp>深入分析问题本质，找到问题的根本原因，可以对症下药帮助我们找到解决方法。不利用结构化思考方法，则容易毫无头绪或只解决表面问题而不能提出务实有效方案。\u003c/p>\u003cp>how那么这个透过结构看问题该怎么做呢？\u003c/p>\u003cp>第一步，大胆假设。可利用前人总结的思考框架比如分析业务战略的3c模型、行业分析的五力模型、分析组织策略的7s模型等；没有适用模型的，可以根据“互不重叠完全穷尽”的MECE原则自己搭建框架。剥离表面问题，找到切入点后，进行大胆假设。\u003c/p>\u003cp>第二步，小心求证：针对上一步假设收集证据，对假设进行结构化验证。如果验证后发现和假设不吻合，则调整假设重新验证，直到看清本质。\u003c/p>\u003cp>第三步，科学呈现：选择合适的方式，比如图示化或金字塔结构表达或其他与内容匹配的形式输出结果，易于对方接受理解。\u003c/p>\u003cp>Where\u003c/p>\u003cp>这个技巧可用于遇到问题没有头绪时，帮我们找解决方案。\u003c/p>\u003cp>为了便于理解，我给大家举个例子。\u003c/p>\u003cp>一个公园里雕像身上近期鸟屎增多，很难清洗干净。\u003c/p>\u003cp>有人提出表面的建议：比如专人的随时清洗，但这成本极高。也有建议用强酸，可是又会腐蚀雕像。这种表面的解决方案都不太可行，让管理者十分头疼。\u003c/p>\u003cp>于是他们开会，结构化的思考，分析问题本质。\u003c/p>\u003cp>第一步，大胆假设：通过mece分析，解决鸟粪问题可以从好清洗和减少鸟屎两方面入手。并推导出是环境因素导致鸟多了的假设。\u003c/p>\u003cp>第二步，小心求证：通过实地调查，发现鸟大量聚在雕像附近吃虫子，而虫子则是被提前开的路灯吸引而来。\u003c/p>\u003cp>第三步，科学呈现：通过以上分析，解决方案呼之欲出，因为方案实在简单，所以选用最直观的表达，一句话：延后半小时开灯，减少蚊虫聚集。\u003c/p>","interaction":"\u003cp>相信大家对原书拆页的内容有了更深的理解，下面进行小组内讨论。请大家认真听一下要演练的场景：你是公司的行政主管，员工反馈餐厅菜变难吃了，请使用透过结构看问题技巧，通过大胆假设、小心求证、科学呈现三步找出解决方法，请大家开始讨论，5分钟后我们请小伙伴来讲解。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>我接到员工投诉后，透过结构分析问题，寻找答案。\u003c/p>\u003cp>第一步，大胆假设。通过人机料法环的结构模型分析问题，因为厨师队伍、食材物料、烧制工艺、后厨环境均稳定，设备虽然也没改变，但设备在使用过程中容易坏，此处假设设备出现变化，导致菜品口味变化。\u003c/p>\u003cp>第二步，小心求证。收集后厨冷库、灶台等与菜品口味大相关度设备的各参数，发现灶台的火变小了。进一步查看，发现是灶台气孔堵塞，再进一步发现是设备点检人员不认真，设备较长期未保养维护。\u003c/p>\u003cp>第三步，科学呈现。两张灶台对比图(1号正常，2号堵塞)，及柱状图表达对应的火焰温度，凸显差距。一方面告知维修部门一天内完成气孔疏通工作。一方面责令餐厅厨师长检查设备维护情况，并建立奖惩机制。\u003c/p>\u003cp>事后复盘的方法可以帮助大家更有效的将拆页拆为己用，想想在过去的一两周内，你或你的同事遇到了什么无措的难题。那时你们都做了什么?焦躁、抱怨?试试今天的透过结构看问题，通过大胆假设、小心求证、科学呈现，是否能帮助找到解决方案。\u003c/p>\u003cp>学习者案例\u003c/p>\u003cp>我一直想提升自己的英语技能，多次下决心要学习，但一直没取得实质结果。这让我十分懊恼和沮丧。甚至觉得我真的不适合学英语。我用学习的透过结构看问题来分析这个情况。\u003c/p>\u003cp>第一步，大胆假设。通过人机料法环的模型看我的英语学习。我学习动机明确、pad等学习硬件充分、学习材料充足、学习方法是考大学时用的适用自己的方式，问题可能出在环境上，假设学习环境有问题。\u003c/p>\u003cp>第二步，小心求证。记录我学习时状态。学习过程中并没有什么外界因素干扰我学习，但进一步查找，发现我的工作生活环境中，缺乏学习的引导因素。没有共同学习者、紧迫感及使用环境。\u003c/p>\u003cp>第三步，科学呈现。金字塔结构展示优化方案。\u003c/p>\u003cp>技能点：催化学习者应用布置任务\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1567610115000,"updated_at":1567610506000,"ria":true},{"id":7264,"topic":"结构表达的技巧","learn_goal":"如何借助总分总结构表达","remark":"李忠秋先生的第二本专著","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"杨颖春","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"\u003cp>【\u003cstrong>学习目标\u003c/strong>】\u003c/p>\u003cp>通过本次学习，学习者能够运用本拆知识总-分结构持思考结构能够表达清晰一件事，达到接受者能清晰知道我们的结论是什么，理论依据是什么。\u003c/p>\u003cp>大家下午好，我叫杨颖春，我的3个标签是公司职员、生命舞者、一级拆书家，今天定级TF2-2，我们先分下组，左边一组右边一组，组内小伙伴互相握下手。\r\n图书介绍 &nbsp;FAB法介绍 &nbsp;\r\n今天我要给大家分享的内容来自李忠秋老师写的《透过结构看世界》。\r\n【F部分：特征，核心“书”】\r\n这本《透过结构看世界》的作者李忠秋老师本身就是一个运用结构化思考的成熟佳品，其所著这本书，通过对结构思考力的剖析和讲解，使你觉察并改善自身的思考结构，养成科学思维的习惯，成为善思、善讲、善写的人才，从而帮助你从思、言、行这三个层次提升个人的实战力。\r\n【A部分：优势，重点是“比较”】\r\n这本书是理论、方法、应用相结合，本书观点鲜明，结构清晰，通俗易懂，给人印象深刻，是实用性非常强的一本书，彩色手绘图示，精美展现，是该书的一大亮点；李忠秋老师围绕着透过结构看世界，层层分解，向我们传达了洞悉本质的思考艺术，为读者树立了运用结构思考力的最佳典范。\r\n【B利益：学习者获得收获】\r\n在汇报工作或者与同事沟通过程等大部分人都存在这样的现象，领导或同事会对你说：你说了这么多到底在说什么，说了半天我一句话也没听懂，只是在浪费我的时间，你到底想表达什么，那么通过对这本书的学习可以告诉你怎样花最少的时间将汇报工作，与同事沟通达到预期甚至意想不到的效果。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10679,"quote":"\u003cp>【R 阅读原文】拆页来自李忠秋《透过结构看世界》之结论先行P74-75节选\u003c/p>\u003cp>&nbsp;“以名举实，以辞抒意，以说出故”，《墨子.小取篇》作为墨家名辩之学的精华所在，对基于清晰思考的表达做了明确的论述，各种事物称为“实”，“实”的称谓便是“名”，比如这是一匹马，“这”就是实，“一匹马”就是名，名与实一起成为“辞”，有了辞才能达意，才叫结论。 如图5-7所示。\u003c/p>\u003cp>想要表达清晰，就必须有结论。无论传达什么信息，都是为了让对方知道结论是什么。如前面提到的机毁人亡的事故，假如你是机场负责人，当你向上级领导汇报时，你首先说结论：“今天发生了一起一等事故。”上级领导一听就明白了事故的严重性。然后，他需要听你讲述发生事故的原因，下一步需要做的工作，准备采取的措施等。若下级行讲发生事故的现象、处理情况等，上级领导会不耐烦甚至勃然大怒。\u003c/p>\u003cp>结论先行不仅仅是先说结论这么简单，重点是要有结论。有一次一家企业的培训负责人很晚打电话给我，希望我帮她修改明天上午的述职报告，第二述职结束后打电话给我反馈了结果。说改之前的报告有同事看过，改完以后的述职报告会那同事也在场。改之前她同事的评价是，看完这个报告能感觉出来她是一个踏踏实实完成工作任务的职业经理人，面改完后的报告体现出，他就是一个有思想的高级职业经理人。到底什么样的变化会有这样的评价呢？其实很简单，就是两个结论的提出。改之前报告分为两部分2014培训工作总结和2015培训工作规划。两个都不是结论，改完之后的是2014年打造具有生命力的培训项目，2015年打造为业务提供支持的培训体系。述职完后，人们可以很容易地记住她的两个观点，而且每个部分下面都有相应的结论作为支撑。这就是有结论和没结论的差别。\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>好，大家都阅读完了本片段，\u003c/p>\u003cp>What：这个片断告诉我们，要想表达清晰，就必须有结论，在日常生活和工作中无论想传达什么信息，都是为了让对方知道结论是什么，先表明观点，然后再依次对观点进行说明，这是一个很好的沟通技巧。\u003c/p>\u003cp>Why：为什么要结论先行呢，书的例子告诉我们领导关注的或同事所关注或会议上要达到的效果都是结论，过程只是对结论进行的论证\u003c/p>\u003cp>How：拆页里已经详细给出了步骤\u003c/p>\u003cp>1、&nbsp;论，结论先行，首先表明总结观点\u003c/p>\u003cp>2、对第一步的一个延伸，再次总结观点\u003c/p>\u003cp>3、依次阐明要点，对观点进行说明\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>在现实中，很多人会说，我们中国人并不习惯这么讲，都是先说原因，再告诉结果，这个沟通方式可能不是很适用，人与人之间在沟通中牵扯到情感时，先抛出一个结论可能会给人感觉目的性特别强，人的理性上接受不了；往往在工作场合中，特别是主题会议，汇报工作，或与同事的沟通，需要结论先行，对结论进行有针对性的讨论，才能提高效率，达到我们的目的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>1、&nbsp; 生活中不一定要用结论先行，特别是在于情感方面不适用。\u003c/p>\u003cp>2、&nbsp; 对于工作中复杂问题，也不适用，复杂的问题需要经过缜密的思才，形成一定的结论，而不是根据经验很轻易的给出一个结论，就像我们所知道的刻舟求剑，纸上谈兵，就是类似这样的。\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>由于公司的产品有颗料停产了，需要对替代的物料进行验证是否可达到相同的功效，这是一个公司的主打产品不能停产，公司上层最终想知道的结果是这颗物料是否能替代原有的物料，所产生的影响，功能性要求是否符合产品本身的种需求，质检主任将测试报告拿给我，十几页的报告全是测试过程，结果只有一句话，未说明可以替代的理由，要知道理由还需要看报告的人自己去梳理；现实工作中，老板关注的是结论是什么，形成结论有哪些观点，再来是形成观点的理论数据是什么，我与质检经理沟通，这个报告呈上去，会有问题，现在的这份报告不是我们这个层次的水平，质检经理听了很有情绪是抗拒的，与他平时的做事习惯不一样，他不想改，让我先把这份报告提交，我回复质检经理，这份报告提交上去只是在浪费老板的时间，你先回想下我刚提的那三个步骤，如果你收到这样的报告你是什么样的心情；后来质检组长按总\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>分\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>总的结构重新书写了报告，先把结论提出来，老板最关注的点写在最前面，针对这个点有几个观点接着写在后面，最后才对观点进行了阐述，我将报告提交给老板，老板是满意的，对我们做了一定的嘉奖。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样做的好处就是：\u003c/strong>处理一些简单的工作、工作汇报、早会等使用结论先行可以节省大家的时间，大家的关注点可以跟宣讲者或组织者有统一的思想，形成共识，在行动上有一致的行动，而不是你说你的，我说我的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2催化学习者应用】\u003c/strong> \u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>，激活场景，\u003c/strong>\u003c/p>\u003cp>请小伙伴想下在今后，会将本片段运用到哪些场合，比如像课程设计、向老板汇报工作、团队建设计划或跨部门协调等，大家试想下有没相类似的场景，可以运用到这个知识片段，我们花2分钟时间组内讨论下，稍后请小伙伴给我们分享下准备把这个技巧用在哪个情景里面。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>用在工作中提交书面报告的时候用，因为老板注意结果，用总-分-总的结构来呈现。\u003c/p>\u003cp>\u003cstrong>分步催化2，催化应用（规划行动步骤）\u003c/strong>\u003c/p>\u003cp>请大家想一下，今天片段中学到的步骤，你会怎样运用到你的场景中？稍后请一位小伙伴分享下“你会怎么做？”\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>三月份做毕业生专项培训，今年在做工作方案的汇报部分，总结会要有新的高度，今年有145号人，新的高度，新的方式，要更加贴近实际操作。\u003c/p>\u003cp>第一步，我们的观点是说在毕业生这个项目里，在一周里收获到个人的成长及跟工作结合的学习乐趣，这个是基本观点\u003c/p>\u003cp>第二步，从三个方面进行，1）日常通用技能点，如时间管理，沟通管理，日常交流方面来做；2）工作技能，了解各个部门的岗位操作及部门间协同，公司制度，行业知识；3）从自我人性面，毕业生到职业心性的成长\u003c/p>\u003cp>第三步，最后总结，这期训练营，实现个人成长突破，从心性和技术上有突破和成长。\u003c/p>\u003cp>\u003cstrong>结束语，\u003c/strong>\u003c/p>\u003cp>谢谢这位小伙伴的分享，他向我们很好的呈现了今天所学习的步骤，论，结论先行，先表明观点，然后再依次对观点进行说明，用总的一个方式，再用一个分的方式，最后再次做个总结，总-分-总方式呈现了汇报工作或培训及分享美好的事物，以他们舒服的方式表达自己的观点，再对观点进行解说，无意间就会产生共鸣，达到我们共同的目标，今天我的分享结论先行，希望能给大家带来收获，今天的拆书到些结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1551088016000,"updated_at":1551131464000,"ria":true},{"id":6871,"topic":"\"掌握结构式的沟通技巧 \"","learn_goal":"轻松有效的搞定对方","remark":"\"为了成为“思考清晰、表达有力、生活清爽、工作高效”的人士，我们有必要掌握一下：收集信息、信息分类、概括总结，这3步有效的结构式沟通技巧。\r\n\r\n\"","level":"TF2-1","duration":18,"status":29,"type":0,"chaishujia":{"username":"林の雪","city":"烟台"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>各位老师大家晚上好！今天跟随我完成这次RIA现场学习后，相信各位老师都能掌握一种结构式的沟通技巧—收集、分类、总结，这种自下而上的金字塔结构，让对方快速并清晰地了解你的意图。（本次学习目的）我们先按现场人数随机分为2组，随后我们组内讨论、组间分享。\u003c/p>\u003cp>下面给大家介绍一下今天的带拆书籍：\u003c/p>\u003cp>F: 这本《透过结构看世界》的作者是李忠秋，是中国结构思考力学院的创始人，这本书从理念、方法、应用三大方面循序渐进地培养、建构我们的结构思考能力。\u003c/p>\u003cp>A: 为贴近实际应用，这本书给我们提供了大量结构思考力的实用工具，把理论学习与实践体验结合起来，做到学以致用。\u003c/p>\u003cp>B: 如果你想成为“思考清晰、表达有力、生活清爽、工作高效”的人士，这本书将教会我们用结构性思考力洞悉事物的本质，当一个人习惯了以结构的视角去审视身边的事物和问题时，一定可以让我们把事物看得清晰、全面，生活和工作也会变得非常有条理和高效。尤其是今天的这个拆页将教会我们一种实用的结构性思考力。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","ratings_count":1,"texts":[{"id":10230,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>《透过结构看世界》拆书片段p133~134页。\u003c/p>\u003cp>在日常生活工作中，我们经常遇到另外一种情况，就是面对一堆素材或信息，需要加以整理、梳理，理出头绪，以便“提纲挈领”。比如工作总结就是如此。在这样的情况下，就需要我们采取自下而上搭建金字塔结构的方式，叫做概括总结做聚合。\u003c/p>\u003cp>采取这种方式有三个步骤。\u003c/p>\u003cp>（1）&nbsp;&nbsp;&nbsp; &nbsp; 收集信息。将能够收集到的信息全部罗列出来。\u003c/p>\u003cp>（2）&nbsp;&nbsp;&nbsp; &nbsp; 信息分类。按照归类分组的原则，确保同一组的信息属于同一个范畴。\u003c/p>\u003cp>（3）&nbsp;&nbsp;&nbsp; &nbsp; 概括总结。将每个分类概括出一个结论。寻找每组信息资料的共性，将共性概括为结论，然后继续往上概括，直到金字塔的塔顶得出最终的结论为止。\u003c/p>\u003cp>我们现在以生活中介绍异性朋友为例，说明此方式的运用。\u003c/p>\u003cp>假如有人向你单位的一位女同事介绍男朋友，你问他那个小伙子怎样呀？他说，那个小伙子真不错，个头高，大学毕业，长相好，待人和气，潇洒活泼，逻辑思维能力强，富有同情心，在大型企业从事设计工作，工资高……\u003c/p>\u003cp>你听完这样的介绍，感觉信息不少，但有些乱。所以你需要将这些信息梳理一下，分成三类，每类给出一个结论，最后概括出一个结论，再向你的女同事介绍，就会很精彩。其金字塔结构如图7-18所示。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这么好的小伙，赶紧hold住！！！\u003c/p>\u003cp>纵向结构的以上两种方式一般都是同时使用的，通过自上而下、自下而上的两方面努力，就能完成一份观点清晰、简明的表达结构。这个过程实际上是确定主题、基于主题进行发散思维，然后进行聚合概括，浓缩成一个打动对方的结论的过程。在这一过程中，结构思考力帮助我们完成了整个构思。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>（不这么做的坏处）在工作、生活中，口头也罢，书面也好，当我们表达3种以上的信息时，一股脑地无头绪地阐述自己的观点，可能对方根本不明白我们到底想表达的是什么？几个意思？有时甚至连我们自己都不知道在聊些什么，闲扯了没用的东西很多，常常造成沟通上的误会，导致工作和生活无法高效顺畅地运转。\u003c/p>\u003cp>（反面案例）比如去年同期同事小邢外出办事，我说好像今年的社保最高最低基数下来了，不知现在是多少？应该有文件了，如果有文就拍下来带回来看看。还有些办公用品需要买，比如：透明文件夹、签字笔、洗涤液等。顺便问问地税个税缴纳手续费什么时候开始办理？还有稳岗补贴什么时候办理？对了，顺便把各银行的对账单取回来…….结果小邢回来后忘了问地税手续费返还的事当时也没跟我说，到了后期需要办理时我才想起来当时忘了跟他确认这件事了；而且我当时最需要的透明文件夹也忘买了，没法只能又让他跑了一趟。\u003c/p>\u003cp>（通过原文拆页建议，转为正面案例）造成我和他都遗忘的后果就是因为我向他传达指令时没有逻辑性和结构性，想到哪儿说到哪儿，一点不清晰，容易让人误解和遗漏。如果按原文中的内容，把让他办的事分类、概括成4部门7件事，即社保处：最高最低基数、稳岗补助；银行：对账单；地税：个税返还；文具店：买文件夹（必须）、签字笔、洗涤剂。这样我们彼此都会一目了然，很清晰高效。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【A1】激活经验\u003c/p>\u003c/td>\u003ctd>\u003cp>2分钟\u003c/p>\u003c/td>\u003ctd>\u003cp>拆书家显像提问设计：\u003c/p>\u003cp>请回顾一下近期我们在与同事、领导、朋友等口头沟通时，当时还自我感觉良好，结果说了一大堆，没进行清晰地归类或概括，对方却完全搞不懂你是什么意思？引发了误解、懊恼、挫败等，想想看这件事究竟是发生在什么时候？可以描述一下当时的具体情境吗？给大家1分钟的时间回想一下，然后拿出1分钟时间在小组内进行分享。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>新建老师分享案例：有一次在职场跟同事说：小王，你要给客户发邮件啊，再把那个验证的事重新做一下，另外稽核的文件发出去了吗？还有什么什么……因为说了太多的事项，没有逻辑和关联性，对方好像也没记住，结果新建自己也很有挫败感，认为自己明明交代得也很清楚啊，也没有涉及太多事项，为什么对方就记不住呢？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>【A1+】催化应用\u003c/p>\u003c/td>\u003ctd>\u003cp>9分钟\u003c/p>\u003c/td>\u003ctd>\u003cp>拆书家催化提问设计：\u003c/p>\u003cp>想一想，如果再遇到类似的情况时，结合刚刚我们学习的原文内容，如果回到当时的场景，你会怎么办呢？用原文中三步骤写一下未来设想：\u003c/p>\u003cp>①&nbsp;&nbsp;&nbsp; 收集信息\u003c/p>\u003cp>②&nbsp;&nbsp;&nbsp; 信息分类\u003c/p>\u003cp>③&nbsp;&nbsp;&nbsp; 概括总结\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>吕老师按照前面所学的三步骤，结合自己的事例分享如下：\u003c/p>\u003cp>①&nbsp;&nbsp;&nbsp; 收集信息\u003c/p>\u003cp>吕老师早晨一到班上，就把当天所有的工作都列出来，列出来后发现每天都有近10多项需要做的工作。（属于收集信息层面）\u003c/p>\u003cp>②&nbsp;&nbsp;&nbsp; 信息分类\u003c/p>\u003cp>然后按照工作内容进行4象限分类：紧急重要（当天必须要押款，押款工作对于安保公司来说是关键要务）；紧急不重要（当天有检查的要应付，尽管是内部检查不重要，但属于紧急事项，必须要当天应对）；不紧急重要（资格考试，虽说目前不紧急，但对于以职称论绩效的企业来说无论对公司还是对个人来说都是重要的事项）；不紧急不重要（车辆保养维护跟其他事项相比而言，属于不紧急也不重要，可以限定时间节点，本周内完成即可）。\u003c/p>\u003cp>③&nbsp;&nbsp;&nbsp; 概括总结\u003c/p>\u003cp>经过上面的信息收集以及信息分类工作后，就可以有条理性地分配工作，然后跟进、确认完成情况即可。\u003c/p>\u003cp>拆书家：吕老师的分享非常好！完全学会并掌握了结构性沟通的三步骤：收集信息、信息分类、概括总结，各位在座的老师们通过上面的分享，也从中了解并熟悉了这种具有逻辑性的结构沟通方式，相信今后大家一定在生活和工作中会将事物看得更清晰、更全面，生活和工作也会因此变得非常有条理和高效。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1545651705000,"updated_at":1545651814000,"ria":true},{"id":6600,"topic":"如何借助总分总结构提升逻辑表达力","learn_goal":"学会总分总结构归纳概括表达要点","remark":"李忠秋先生关于结构逻辑的第二本专业书籍","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"杨颖春","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"【学习目标】\r\n通过本次学习，学习者能够运用本拆知识能够表达清晰一件事，达到接受者能清晰知道我们的结论是什么。\r\n分组：\r\n我叫杨颖春，我的3个标签是公司职员、生命舞者、一级拆书家，今天定级TF2-2，我们先分下组，左边一组右边一组，\r\n图书介绍 FAB法介绍 \r\n今天我要给大家分享的内容来自李忠秋老师写的《透过结构看世界》。\r\n【F部分：特征，核心“书”】\r\n这本《透过结构看世界》的作者李忠秋老师本身就是一个运用结构化思考的成熟佳品，其所著这本书，通过对结构思考力的剖析和讲解，使你觉察并改善自身的思考结构，养成科学思维的习惯，成为善思、善讲、善写的人才，从而帮助你从思、言、行这三个层次提升个人的实战力。\r\n【A部分：优势，重点是“比较”】\r\n这本书是理论、方法、应用相结合，本书观点鲜明，结构清晰，通俗易懂，给人印象深刻，是实用性非常强的一本书，彩色手绘图示，精美展现，是该书的一大亮点；李忠秋老师围绕着透过结构看世界，层层分解，向我们传达了洞悉本质的思考艺术，为读者树立了运用结构思考力的最佳典范。\r\n【B利益：学习者获得收获】\r\n你在汇报工作时是否有被领导训斥你说了这么多到底在说什么，或与同事沟通项目进展时，同事问你找我到底要我做什么，我现在没空听你长篇大论，等你想清楚了在找我等等，那么这本书可以告诉你怎样花最少的时间将汇报工作，与同事沟通达到预期甚至意想不到的效果。","ratings_count":1,"texts":[{"id":9930,"quote":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>R\u003c/strong>\u003cstrong>】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>【R 阅读原文】拆页来自李忠秋《透过结构看世界》之结论先行P74-75节选\u003c/p>\u003cp>&nbsp;“以名举实，以辞抒意，以说出故”，《墨子.小取篇》作为墨家名辩之学的精华所在，对基于清晰思考的表达做了明确的论述，各种事物称为“实”，“实”的称谓便是“名”，比如这是一匹马，“这”就是实，“一匹马”就是名，名与实一起成为“辞”，有了辞才能达意，才叫结论。 如图5-7所示。\u003c/p>\u003cp>想要表达清晰，就必须有结论。无论传达什么信息，都是为了让对方知道结论是什么。如前面提到的机毁人亡的事故，假如你是机场负责人，当你向上级领导汇报时，你首先说结论：“今天发生了一起一等事故。”上级领导一听就明白了事故的严重性。然后，他需要听你讲述发生事故的原因，下一步需要做的工作，准备采取的措施等。若下级行讲发生事故的现象、处理情况等，上级领导会不耐烦甚至勃然大怒。\u003c/p>\u003cp>结论先行不仅仅是先说结论这么简单，重点是要有结论。有一次一家企业的培训负责人很晚打电话给我，希望我帮她修改明天上午的述职报告，第二述职结束后打电话给我反馈了结果。说改之前的报告有同事看过，改完以后的述职报告会那同事也在场。改之前她同事的评价是，看完这个报告能感觉出来她是一个踏踏实实完成工作任务的职业经理人，面改完后的报告体现出，他就是一个有思想的高级职业经理人。到底什么样的变化会有这样的评价呢？其实很简单，就是两个结论的提出。改之前报告分为两部分2014培训工作总结和2015培训工作规划。两个都不是结论，改完之后的是2014年打造具有生命力的培训项目，2015年打造为业务提供支持的培训体系。述职完后，人们可以很容易地记住她的两个观点，而且每个部分下面都有相应的结论作为支撑。这就是有结论和没结论的差别。\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>好，大家都阅读完了本片段，\u003c/p>\u003cp>What：这本书告诉我们，要想表达清晰，就必须有结论无论传达什么信息，都是为了让对方知道结论是什么，先表明观点，然后再依次对观点进行说明。\u003c/p>\u003cp>Why：为什么要结论先行呢，书的例子告诉我们领导关注的或同事所关注的是结果，过程只是对结果进行的论证\u003c/p>\u003cp>How：拆页里已经详细给出了步骤\u003c/p>\u003cp>1、论，结论先行，首先表明总结观点\u003c/p>\u003cp>2、依次阐明要点，对观点进行说明\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>1、&nbsp; 结论先行，在于情感方面不适用，人与人之间在沟通中牵扯到情感时，先抛出一个结论可能会给人感觉目的性特别强，人的理性上接受不了。\u003c/p>\u003cp>2、&nbsp; 对于工作中复杂问题，也不适用，复杂的问题需要经过缜密的思才，形成一定的结论，而不是根据经验很轻易的给出一个结论，就像我们所知道的刻舟求剑，纸上谈兵，就是类似这样的。\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>由于公司的产品有颗料停产了，需要对替代的物料进行验证是否可达到相同的功效，这是一个公司的主打产品不能停产，公司上层最终想知道的结果是这颗物料是否能替代原有的物料，所产生的影响，功能性要求是否符合产品本身的种需求，质检组长将测试报告拿给我，十几页的报告全是测试过程，结果只有一句话，未说明可以替代的理由，要知道理由还需要看报告的人自己去梳理，因此被我退件了，报告是给决策者看的，他关心的结论是什么而不过是过程，因此报告先说结果是否可替代，接着说可以替代的理由，最终再整理理由形成的原因在哪，这样可以节省看报告人的时间。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样做的好处就是：\u003c/strong>处理一些简单的工作、工作汇报、早会等使用结论先行可以节省大家的时间，大家的关注点可以跟宣讲者或组织者有统一的思想，形成共识，在行动上有一致的行动，而不是你说你的，我说我的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>催化学习者应用】\u003c/strong> \u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>，激活场景，\u003c/strong>\u003c/p>\u003cp>请小伙伴想下在今后，会将本片段运用到哪个场景，比如像课程设计、老板汇报工作、团队建设计划、跨部门协调等，大家思考想出具体场景，然后运用本片段知识加工一个例子，说明你在此场景下可以运用本片段知识，我们花3分钟时间组内讨论下，稍后请小伙伴给我们分享下他的场景。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>在过2周要做线上拆书，在准备线上课程设计时会运用今天所学片段。\u003c/p>\u003cp>\u003cstrong>分步催化\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>，催化应用（规划行动步骤）\u003c/strong>\u003c/p>\u003cp>请大家想一下，今天片段中学到的步骤，你会怎样运用到你的场景中？稍后请一位小伙伴分享下“你会怎么做？”\u003c/p>\u003cp>大家讨论的非常激烈，现在我们请这位小伙伴分享下他会怎么做。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>我在准备拆研班线上一小时的预备表内容，学了本片段的知识，我可以将本片段的知识应用在预备表整个环节的设计当中，在自我介绍和图书介绍完之后，我会增加一个学习地图，学习地图呈现三个片段讲了什么内容，同时在每个片段要做哪些事项，比如说片段一关联自己过往经验，片段三应用此片段到未来的运用，学习地图包含了三个片段的知识点，还有学习者在学习过程当中预期的心理状态把他融到学习地图里；接下来讲三个片段具体讲解的呈现；三个片段讲解完后，再来一个总的归纳总结，对三个片段进行一个概括；这样的话，学习者对于片段的知识有一个很清晰的脉络。\u003c/p>\u003cp>\u003cstrong>结束语，\u003c/strong>\u003c/p>\u003cp>谢谢这位小伙伴的分享，他向我们很好的呈现了今天所学习的步骤，论，结论先行，先表明观点，然后再依次对观点进行说明，用总的一个方式，里面有一个学习地图，接着对这么内容进行一些分解，到了最后又给我们把今天所学的东西做了一个总的概括，是非常好的一个案例，今天学习的目标，汇报工作也好，分享美好的事物也好，以他们舒服的方式表达自己的观点，再对观点进行解说，无意间就会产生共鸣，达到我们共同的目标，今天我的分享结论先行，希望能给大家带来收获，今天的拆书到些结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543404069000,"updated_at":1543404069000,"ria":true},{"id":6362,"topic":"SCQA法——分析帮助确定问题","learn_goal":"通过SCQA4个步骤，依靠分析事实和数据归纳出结论。","remark":"宣传介绍:\r\n我们遇到一个问题，有没有，凭直觉就得出结论的情况,这样的结论是否正确呢？有没有进行过认真的思考。其实，遇到问题，不是凭直觉，而是通过一个范式，可以对情况和数据进行深入的分析，得出正确的结论。你想掌握这个正确的范式吗？那么让我们期待这次拆除课吧。\r\n\r\n","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"骏飞","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"【自我介绍1’】\r\n大家好，我是骏飞。刚从分舵第九期RIA训练营毕业，目前正在成为拆书家的路上升级打怪，今天是我的1-1便签分享。我是一个进入中年焦虑期的大叔，但我不想成为一个油腻的大叔。那怎么才能不油腻呢，我给自己一个解决方案，那就是终身学习、立即实践。所以我就参加了拆书帮，跟了我的师傅若尘。我的三个标签是：终身学习者、企业兼职内训师、财经和认知提升专栏爱好者。\r\n【拆书和拆书帮是什么2’】\r\n我所理解的“拆书”是一种学习的方法论。强调以学习者为中心而不是以知识为中心，也就是说，重要的不是快速找到书中的重点，重要的是能不能为我创造价值，为我解决问题。把书中的知识拆为己用，转化为自己的能力，这是我们关注的。拆书主要使用RIA便签法。RIA分为5步： \r\n1.确定你要读的是致用类图书，这是拆除法的适用边界。\r\n2.R-用较快的速度阅读原文，如果遇到书中的理论问题，想一想，这个问题对我有多重要？ \r\n3.I-用自己的语言简要重述相关信息。可以是对自己的启发，或对自己的提醒。写在I便签上。\r\n4.A1-对同一个事情，问自己有没有经历过相似的经历，或听过过、见到过相应的事情，这是你的经验，拿A1便签记下来。\r\n5.规划自己如何运用，写下行动的目标，再规划自己如何行动。写在A2便签上。\r\n拆书帮：拆书帮是一个运用拆书法做阅读和分享的学习爱好者社群。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。拆书帮是一个公益性的自组织;是一群美的人，他们在一起成长；一群将拆为己用的人。他们热爱蜕变的感觉；他们，在一起吸收书给我们的力量，在提取总结书中的能量，在把精髓分享给所有爱好读书的人们。","ratings_count":0,"texts":[{"id":9660,"quote":"\u003ch1>SCQA分析帮助确定问题\u003c/h1>\u003cp>我们能够发现问题，很多时候是因为看到了现象，之后凭直觉归结到一个问题。正确的做法是依靠脚踏实地地分析事实和数据，归纳出的结论才是问题。运用结构思考中描写序言的工具SCQA，可以有效地确定和描述出问题。\u003c/p>\u003cp>如下所示。\u003c/p>\u003cp>S：描述当前的状态\u003c/p>\u003cp>C：描述时间期望达到的状态及发生的冲突\u003c/p>\u003cp>Q：针对冲突提出问题\u003c/p>\u003cp>A：结合问题给出答案\u003c/p>\u003cp>SCQA使用的四步骤。用 SCQA方法时，可以遵循这样的四个步骤。\u003c/p>\u003cp>1)&nbsp;&nbsp;&nbsp;&nbsp; 描述当前的状态，即 S。这里的描述要尽量具体，比如时间、地点、当事人、发生了什么现象、现象发生到什么程度。\u003c/p>\u003cp>2)&nbsp;&nbsp;&nbsp;&nbsp; 描述事件期望达到的状态以及发生的冲突，即 C。 C是问题或障碍，是因为现状和期望产生了落差。这个落差并非只是不良状态，也有可能是因为超过预期，证明这或许是一个千载难逢的良机。\u003c/p>\u003cp>3)&nbsp;&nbsp;&nbsp;&nbsp; 针对冲突提出疑问，即 Q。这个过程是确定去解决什么，是把冲突聚焦为待解决问题的过程。\u003c/p>\u003cp>4)&nbsp;&nbsp;&nbsp;&nbsp; 给出问题可能的答案，即 A。基于问题思考假设的方案，如果是简单问题，这时 A可以很容易获得；如果问题所处的情境过于复杂，就要经过仔细分析找到关键要素并建立假设，此时的 A不用急于给出。\u003c/p>","explains":"\u003cp>\u003cstrong>【拆页介绍】\u003c/strong>\u003c/p>\u003cp>书名: 《透过结构看世界》作者：李忠秋\u003c/p>\u003cp>图书简介：这本书介绍结构化思考的原理和应用，是《金字塔原理》的中国化运用。\u003c/p>\u003cp>I&nbsp;拆书家讲解引导\u003c/p>\u003cp>我选择的这个便签讲的是运用SCQA法确定问题。在确定问题过程中，我们很容易在看到现象后，凭直觉就归结到一个问题，这样归结的问题有可能比较浅，而忽略真正的问题。科学的做法是采用结构化的思考方法。具体就是分为四步：第一步S，描述当前的状态；第二步C：描述事件期望达到的状态以及发生的冲突；第三步Q：针对冲突提出问题；第四步A：给出问题可能的答案。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>这个便签之所以我要挑出来是因为我特别受启发。因为我凭直觉得出错误结论的案例特别多。就比如昨天我和我夫人一起吃晚饭，本来两个人边吃边聊非常开心，气氛非常好。但是这顿饭接近尾声时，我接到了正在家里陪孩子的母亲的电话。我母亲说孩子老在问我和夫人什么时候回去，很想我们。这个时候我就没心思吃饭了，匆匆结完账就领着夫人往家里赶。我在前面快步狂奔，但转头就发现夫人走得挺慢，似乎是闲庭信步，这个时候我蹭的一下就来气了，大声说：“走快点啊，孩子在家里等着呢”，然后夫人就一脸不高兴，仍是慢慢吞吞的走，一路上两个人都没有说话了。\u003c/p>\u003cp>A1+\u003c/p>\u003cp>回想一下昨天的经过，我就利用SCQA法来确定我和夫人之间的问题。S：我们从一个休闲的状态转变为匆忙赶回家的状态。C:我希望夫人走快点、早点回家，和夫人不情不愿，和我怄气之间的冲突。Q：夫人为什么没和我一样着急呢？她的诉求是什么？A：我们很久没这么没有压力，放松的在一起吃饭聊天了。你看，通过结构化的思考，我们就找到了真正的问题，就是我夫人很珍惜这短暂的两人相处的时光。\u003c/p>\u003cp>A2\u003c/p>\u003cp>我希望下周在单位利用SCQA法，找出我工作效率不高的原因。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1540907518000,"updated_at":1540907518000,"ria":true},{"id":5243,"topic":"分步催生聚焦问题","learn_goal":"分步催生聚焦问题","remark":"SCQA是一种的序言写作方法，序言内容，可以解决读者一个疑惑或是某个事件的解决方案。将写序言的方法用到我们自身上，就如遇到矛盾冲突时，只有知道什么是我们的问题，那样才是走在解决问题的道路上。","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"无敌","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;我先来分组，每3人一组。\r\n我是无敌，我今天的拆书等级是TF1-2，我是一名写文档码农,撰写产品说明书。我非常喜欢自己的网名无敌，能够让大家很快就记住，回忆起来也很容易。我要做一个温暖世界的人。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":8362,"quote":"\u003cp>下面开始阅读拆页，看完箭头位置的内容\u003c/p>","explains":"\u003cp>拆页的SCQA是一种的序言写作方法，序言内容，可以解决读者一个疑惑或是某个事件的解决方案。将写序言的方法用到我们自身上，就如遇到矛盾冲突时，只有知道什么是我们的问题，那样才是走在解决问题的道路上。\u003c/p>\u003cp>掌握这种方法，可以有如下四个顺序步骤：\u003c/p>\u003cp>S描述当前状态，\u003cstrong>要具体\u003c/strong>，C事件与期望的状态\u003cstrong>冲突\u003c/strong>，冲突带来的可能是阻碍，也可以是正向积极的发展，Q用提问的方式\u003cstrong>聚焦待解决\u003c/strong>问题，A不是那么复杂问题直接给出答案，如果问题比较复杂，为了避免主观臆断和偏见，你需要\u003cstrong>进行分析和验证\u003c/strong>。\u003c/p>\u003cp>&nbsp; 理解后,请大家把S-C-Q-A,填入对应的括号里。\u003c/p>\u003cp>\u003cstrong>①&nbsp; \u003c/strong>\u003cstrong>（S）\u003c/strong>\u003c/p>\u003cp>婚庆场地，国企单位，场地里铺着地毯，规定不让嗑瓜子花生，带皮物品。\u003c/p>\u003cp>\u003cstrong>②&nbsp; \u003c/strong>\u003cstrong>（C）\u003c/strong>\u003c/p>\u003cp>老爸不同意，仪式40分钟，不让嗑瓜子，小盘里的干果很快就吃完了，对喝酒的人就爱吃花生。他的同事们会受埋怨他。\u003c/p>\u003cp>\u003cstrong>③&nbsp; \u003c/strong>\u003cstrong>（Q）\u003c/strong>\u003c/p>\u003cp>分析情况后，排除掉一个冲突，规定还是规定，要遵守。因此问题聚焦到不嗑瓜子花生，如何保证来的客人满意？\u003c/p>\u003cp>\u003cstrong>④&nbsp; \u003c/strong>\u003cstrong>（A）\u003c/strong>\u003c/p>\u003cp>a， 找替代品，去皮瓜子、花生，增加小饼干、小点心、西梅\u003c/p>\u003cp>b， 仪式中补充一次，或者一次放两盘\u003c/p>\u003cp>c， 现场发牌红包，调动大家互动，或者抽个奖啥的。\u003c/p>","interaction":"\u003cp>这道题的结果就是顺序的S-C-Q-A，两旁的小伙伴的答案都是正确。\u003c/p>\u003cp>从一些简单生活小案例着手，更容易理解知识。很多人选择职场技能是学习英语，但并非当前工作需要，不了了之；自己的公众号文章已经停更好久了，周末想着有时间了，却有一场精彩的拆书活动很想去听。跟着教练在健身，但是因为领导安排了一次出差，要中断了。\u003c/p>\u003cp>\u003cstrong>A1\u003c/strong>：现在到了演练环节，学习拆页我们知道用SCQA去聚焦问题，请想想你的过往经历和相关经验，你曾经遇到过的困扰、担忧、两难的事情，你是如何做的，请在小组内分享, 时间5分钟，组内推选出一位小伙伴分享自己的案例。\u003c/p>\u003cp>A1：分享者案例如下\u003c/p>\u003cp>（S）在他的工作中，客户提出需求后，委托公司做策划执行方案，这个执行方案由他们小组做。（C）遇到过某些客户不认可方案内容，而他会认为方案非常专业，必须这么做。（Q）如何让事情能够继续下去？（A）他们修改方案，按客户的要求执行方案。刚刚小组分享中，讨论出了新的应对方法：开始先按照客户想法最快做出成品，因为客户的不专业，成品会有不妥，用实事求，是让客户知道和理解他们的方案。\u003c/p>\u003cp>\u003cstrong>&nbsp; A2\u003c/strong>\u003cstrong>：\u003c/strong>学习了今天的方法是：\u003cstrong>SCQA\u003c/strong>\u003cstrong>聚焦问题。\u003c/strong>\u003c/p>\u003cp>请大家用下面的模板写出，你未来一周可能工作中，生活中会遇到的困扰之事，写下做法，能写出SCQA，你基本已经掌握的这套方法。\u003c/p>\u003cp>\u003cstrong>S\u003c/strong>\u003cstrong>：可预见会发生什么事情？_____________________________________\u003c/strong>\u003c/p>\u003cp>\u003cstrong>C\u003c/strong>\u003cstrong>：有什么冲突？_______________________________________________\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Q: \u003c/strong>\u003cstrong>要解决什么问题？___________________________________________\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A: \u003c/strong>\u003cstrong>给出解决答案_______________________________________________\u003c/strong>\u003c/p>\u003cp>A2：学习者现场行动案例如下\u003c/p>\u003cp>（S）一位新客户向学习者所在公司，提出金融方面的需求。（C）公司给出方案后，客户提出与他的需求不一样，而公司也坚持方案是专业和正确的，双方各坚持己见。（A）先按照客户需求做最小化实现，在过程实现中逐渐求证公司方案的正确，引导客户投向公司方案，达到双发不冲突的共赢解决。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1528006839000,"updated_at":1531747197000,"ria":true},{"id":4287,"topic":"SCQA法，分析帮助确定问题","learn_goal":"通过SCQA4个步骤，依靠分析事实和数据归纳出结论。","remark":"宣传介绍:\r\n我们遇到一个问题，有没有，凭直觉就得出结论的情况,这样的结论是否正确呢？有没有进行过认真的思考。其实，遇到问题，不是凭直觉，而是通过一个范式，可以对情况和数据进行深入的分析，得出正确的结论。你想掌握这个正确的范式吗？那么让我们期待这次拆除课吧。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘雅恕","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1513857452000,"updated_at":1513857452000},{"id":1389,"topic":"三点帮你养成优化思考结构的习惯。","learn_goal":"顺利通过2-4","remark":"《透过结构看世界》内容简介:本书主要关注点是结构化思考领域。作者李忠秋是结构思考力学院的创始人、首席培训师、思考力管理咨询公司总裁。结构化思考被誉为中国的金字塔原理。该书读起来生动有趣，形象到位，案例丰富，是一本难得的能将思考力讲的深入浅出的一本好书。我们说世间万物皆有结构。楼房有结构、文章有结构、表达也有结构。当我们尝试着从结构的视角看待身边的事物和问题，会把问题看的更加清晰，表达出来的内容也会更有说服力。结构思考力，就是让你透过结构看世界。让我们思考清晰、表达有力、生活清爽、工作高效。","level":"TF2-3","duration":20,"status":0,"type":0,"chaishujia":{"username":"故……","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，每一次实践就是一次成长。","ratings_count":0,"texts":[{"id":3886,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":3887,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1479823169000,"updated_at":1479823169000},{"id":925,"topic":"结论先行，以上统下","learn_goal":"结论先行，以上统下","remark":"","level":"TF2-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"张臻凯","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"张臻凯，培训，标签1、小资；2、进取心；3、追求圆满。根据参加人数分为2-3组，每组3-5人","ratings_count":0,"texts":[{"id":2865,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>结论先行，以上统下\u003c/strong>\u003c/p>\u003cp>“以名举实，以词抒意，以说出故”。要想表达清晰，就必须有结论。例如：要汇报机毁人亡的事故，首先先说结论：“今天发生了一起一等事故”，上级一听就明白了事故的严重性，然后，他需要听你讲发生原因，下一步工作计划和准备采取的措施等。若下级先讲事故现象，处理情况等，上级会不耐烦甚至勃然大怒。\u003c/p>\u003cp>表达的时候只有辞还不够，还必须要说明这个结论的理由，称为“故”，有了理由的结论才能成立，可以理解为以上统下。\u003c/p>\u003cp>举个例子：当你出门上班的时候，你的家人对你说：\u003c/p>\u003cp>（结论）“请你带把伞”\u003c/p>\u003cp>为什么？\u003c/p>\u003cp>（理由）“因为天气预报说今天有大雨”\u003c/p>\u003cp>以上统下有3个方面非常重要：\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）有结论\u003c/strong>\u003cstrong>&nbsp;&nbsp; \u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>）有理由\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>）结论和理由相联系。\u003c/strong>\u003c/p>\u003cp>结论和理由通常用“因为”、“所以”等因果链接词连接。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>组织简单的对话或问题时，我们可以把理由放在前面，但当问题比较复杂，理由比较多的情况下，还是先讲结论，再讲若干条理由，显得更加有条理，论据更充分，也能避免听者的猜测。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 大家都知道“说清楚”和“听懂”是两个维度的问题，那如何让听众和说者在一个频道上呢？\u003c/p>\u003cp>&nbsp; &nbsp; 其实是有技巧的。技巧也很简单，就是把你的想表达的结论放在表达的最前端，然后再考虑支持核心思想的论据按重要程度、关联度等因素按层次表达出来。但要把握一点：理由一定要支持你的结论，最好层层递进。总结成八个字就是“结论先行，论据充分”。\u003c/p>\u003cp>&nbsp; &nbsp; 如果不这么做，那效果就是鸡同鸭讲，自说自话了。这里我们来看一个比较糟糕的例子：秘书汇报会议的过程：领导好，陈总说他不能参加下午3点会议；小陈说可以晚点开会，但明天10:30前要见客户，所以不要安排在明天10点半前；李秘书说唐总明天晚上才能飞回来；会议室明天已经预定了，但周四可以。会议时间放在周四上午11点比较合适，您看行吗？如果你是领导听了秘书这通汇报，有啥感觉？是不是有一堆乱麻的感觉，不知所谓。\u003c/p>\u003cp>&nbsp; &nbsp; 但如果我们把握好“结论先行，论据充分”这个基本原则，换个说法：领导，今天的会议改成周四上午11点，可以吗？因为这样陈总、唐总都方便，小陈也能参加，并且本周只有这天会议室没有被预定。\u003c/p>\u003cp>&nbsp; &nbsp; 大家体会一下这样的汇报，结论前置，然后在按导致事情变化的原因，按重要程度先说参会人员，再讲会议室。在说人的时候，又按职务高低进行排序，这样重新考虑充分的理由并且按照重要度排序的汇报，充分体现论据的重要性和层层递进的要求，这样是不是更能让人理解呢？\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;A1： 现在请大家按小组分享下自己或者身边是不是有这样的伙伴，曾经向领导汇报或者同事工作沟通的时候，说了一大堆，没有焦点，最后听众忍无可忍得说到：你到底想说啥？温馨提示：本环节时间3分钟，希望大家尽量表达，请组长控制时间。。。。。请各小组选派一个伙伴做简单分享\u003c/p>\u003cp>&nbsp; &nbsp; 1小组：我给领导汇报我一个星期做了多少事，然后领导就批评我没有重点；\u003c/p>\u003cp>&nbsp; &nbsp; 2小组、我有个同事，领导问他工作进度。他就给领导发一个很长很长的邮件，里面详细记录他几点起床，干了哪些事情，结果经常被领导批评。现在领导看到他的邮件，都懒得看了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;A1+：在刚刚的分享中，如果让你就案例使用“结论先行，论据充分”的方法，你会怎么重新整理沟通内容？时间5分钟，请组长控制时间。。。。请每个小组选派代表分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;1小组：以后汇报会说这个星期一共拜访了多少客户，其中签单多少，有意向多少，没签需要公司的支持是哪些，还有多少是暂时没有需求的。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;2小组：定期将手上工作进度向领导做汇报，汇报分为第一部分已完成情况，第二部分要完成或者超额完成目标需要的资源，第三部分工作上的困难，需要领导支援的。\u003c/p>\u003cp>&nbsp; &nbsp; 感谢大家积极参与，希望通过今天的拆书，能在以后的沟通、汇报时提纲挈领，做到有礼有节。我的2-1拆书到此结束。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474250128000,"updated_at":1474250128000,"ria":true},{"id":157,"topic":"疑问回答式分解法","learn_goal":"掌握“疑问回答式分解法”的简易结构。","remark":"看到这个主题，我知道你们想问什么……\r\nQ1:“疑问回答式分解”跟我有毛线关系？我凭什么要来听你叨叨逼这个？\r\nA1：因为我知道“疑问回答式分解”结构可以帮你把你的想法和诉求表达得像悬疑小说一样引人入胜！指哪打哪，百发百中！我还知道！你在求加薪！谈晋升！卖产品！拉风投！但你一张嘴说话你的金主就想睡觉！\r\nQ2：“疑问回答式分解”到底是什么玩意？你凭什么说“疑问回答式分解”指哪打哪百发百中？\r\nA2：“疑问回答式分解”是李忠秋老师《透过结构看世界》书中介绍的一种表达结构。它根据人纵向思维模式，先简明阐述结论，抓住金主“自上而下想问题，打破砂锅问到底”的思维特点，建立起简明易懂的表达结构。","level":"TF2-2","duration":20,"status":0,"type":1,"chaishujia":{"username":"不如跳舞","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1457669082000,"updated_at":1457669082000}]};